export interface ProgramDay { title: string; body: string; read?: string; ask?: string; }
export interface Program { id: string; icon: string; color: string; title: string; subtitle: string; dayCount: number; days: ProgramDay[]; }

export function getPrograms(lang: Lang): Program[] {
  return PROGRAMS_RAW.map((p) => ({
    id: p.id, icon: p.icon, color: p.color,
    title: pick(p.title, lang), subtitle: pick(p.subtitle, lang), dayCount: p.days.length,
    days: p.days.map((d) => ({ title: pick(d.title, lang), body: pick(d.body, lang), read: d.read?.[lang], ask: d.ask?.[lang] })),
  }));
}

export function getProgram(id: string, lang: Lang): Program | undefined {
  return getPrograms(lang).find((p) => p.id === id);
}

// ─── İlerleme (cihazda) ───────────────────────────────────
const KEY = (id: string) => `stoikos_program_${id}`;

export async function getProgress(id: string): Promise<number[]> {
  const raw = await AsyncStorage.getItem(KEY(id));
  return raw ? JSON.parse(raw) : [];
}

export async function setDayDone(id: string, day: number, done: boolean): Promise<number[]> {
  const cur = new Set(await getProgress(id));
  if (done) cur.add(day);
  else cur.delete(day);
  const arr = [...cur].sort((a, b) => a - b);
  await AsyncStorage.setItem(KEY(id), JSON.stringify(arr));
  return arr;
}

/**
 * Yolculuğu baştan başlat.
 *
 * Stoacı pratiğin kendisi tekrar üzerine kurulu — Marcus aynı defteri yıllarca
 * tuttu, yeni bir program aramadı. Bitmiş bir programı yeniden açabilmek,
 * yeni içerik üretmeden sonsuz tekrar veriyor.
 *
 * Kapanış yansıması bayrağı da siliniyor: yolculuk yeniden yaşanacaksa
 * sonunda yeniden yazılabilmeli.
 */
export async function resetProgress(id: string): Promise<void> {
  await AsyncStorage.multiRemove([KEY(id), REFLECT_KEY(id)]);
}

// ─── Kapanış yansıması (program başına bir kez sorulur) ───
const REFLECT_KEY = (id: string) => `stoikos_program_reflected_${id}`;

export async function hasReflected(id: string): Promise<boolean> {
  return (await AsyncStorage.getItem(REFLECT_KEY(id))) === '1';
}

/** Yazıldı ya da atlandı — ikisinde de bir daha sorulmuyor. */
export async function markReflected(id: string): Promise<void> {
  await AsyncStorage.setItem(REFLECT_KEY(id), '1');
}
